  + '.mo-lever{position:absolute;left:22px;right:30px;bottom:30px;height:10px;border-radius:5px;background:linear-gradient(180deg,#F0D28C,#B8935A);transform-origin:10% 50%;transform:rotate(-6deg);transition:transform .06s;}'
  + '.mo-knob{position:absolute;right:20px;bottom:36px;width:30px;height:18px;border-radius:50% 50% 40% 40%;background:#1B1B1B;transition:transform .06s;}'
